source('mp10_hypothesis_followup_v2/scripts/common.R')
a<-rd('SREBF_corrected_profile_AUCell.tsv.gz');pr<-old('pseudobulk_profiles.tsv');reg<-rd('model_registry.tsv')[kind=='scenic_activity'];out<-list();membership<-list()
for(i in seq_len(nrow(reg))){r<-reg[i];ids<-pr[if(r$patient=='main')main_patient else replacement_patient & TRUE];ids<-ids[n_cells>=r$min_cells];if(r$setting=='common_H05'){ok<-ids[profile_type%in%c('H05','H10','H50','L50'),.N,by=sample_uid][N==4,sample_uid];ids<-ids[sample_uid%in%ok]};ok<-ids[profile_type%in%c(r$state,'L50'),.N,by=sample_uid][N==2,sample_uid];ids<-ids[sample_uid%in%ok&profile_type%in%c(r$state,'L50')];v<-a[mask==r$mask&regulon==paste0(r$y,'(+)')];d<-merge(ids,v,by='profile_id');w<-dcast(d,sample_uid+dataset+patient_uid_recorded~profile_type,value.var='mean_AUCell');w[,delta:=get(r$state)-L50];n<-nrow(w);status<-'not_evaluable';reason<-'';bt<-se<-lo<-hi<-pv<-NA_real_;nt<-rd('scenic_corrected_regulon_edges.tsv')[TF==r$y & !target%in%if(r$mask=='M20')M20 else character(),uniqueN(target)];if(n<4)reason<-'fewer_than_4_paired_units'else if(n-1<3)reason<-'residual_df_below3'else if(nt<5)reason<-'fewer_than5_regulon_targets'else{bt<-mean(w$delta);se<-sqrt(sum((w$delta-bt)^2)/(1-1/n)^2/n^2);pv<-2*pt(-abs(bt/se),n-1);lo<-bt-qt(.975,n-1)*se;hi<-bt+qt(.975,n-1)*se;status<-'completed'};out[[i]]<-cbind(r,data.table(status=status,reason=reason,beta=bt,SE=se,CI_low=lo,CI_high=hi,P=pv,n_specimens=n,n_recorded_patient_units=uniqueN(w$patient_uid_recorded),n_datasets=uniqueN(w$dataset),residual_df=n-1,design_rank=1,n_targets=nt,method='paired AUCell difference OLS HC3 t',effect_unit='mean AUCell High minus Low',input_hash=digest(list(w,r,nt),algo='sha256')));w[,model_id:=r$model_id];membership[[i]]<-w}
z<-rbindlist(out,fill=TRUE);z[,q:=p.adjust(P,'BH',n=unique(planned_n)),by=FDR_family];z[,testable_n:=sum(is.finite(P)),by=FDR_family];put(z,'recovered_SCENIC_model_results.tsv');put(rbindlist(membership,fill=TRUE),'recovered_SCENIC_model_membership.tsv.gz');thread_audit('SCENIC_effects_complete')
